DECIDING = ("meaning_reviewed", "reviewed", "flagged")


def fill_review_states(apps, schema_editor):
    """A ReviewState for every sentence and layer approved or flagged so
    far, from its latest approval or flag. Approvals are left unchecked:
    staff/review.py's refresh compares them with their sentence the first
    time their layer is opened."""
    ReviewEvent = apps.get_model("translation", "ReviewEvent")
    ReviewState = apps.get_model("translation", "ReviewState")
    latest = (ReviewEvent.objects.filter(action__in=DECIDING)
              .order_by("sentence_id", "language", "-created_at", "-id").distinct("sentence_id", "language")
              .values_list("id", "sentence_id", "language", "action", "sentence__source_edition__language"))
    ReviewState.objects.bulk_create(
        (ReviewState(sentence_id=sentence_id, layer=language or original, event_id=pk,
                     state="flagged" if action == "flagged" else "approved")
         for pk, sentence_id, language, action, original in latest.iterator()),
        batch_size=2000)


